import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const sceneRoot=$('#scene');
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,2)); renderer.setSize(sceneRoot.clientWidth,sceneRoot.clientHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15; sceneRoot.appendChild(renderer.domElement);
const scene=new THREE.Scene(); scene.background=new THREE.Color('#a9c5e1'); scene.fog=new THREE.Fog('#a9c5e1',18,45);
const camera=new THREE.PerspectiveCamera(36,sceneRoot.clientWidth/sceneRoot.clientHeight,.1,100); camera.position.set(6,5.2,9);
const target=new THREE.Vector3(0,1.3,0); let radius=11, theta=.56, phi=1.1;
const ambient=new THREE.HemisphereLight(0xe4efff,0x64506f,2.1); scene.add(ambient);
const sun=new THREE.DirectionalLight(0xffe6c6,3.2); sun.position.set(-4,9,5); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); scene.add(sun);
const fill=new THREE.DirectionalLight(0x9b8cff,1.2); fill.position.set(4,4,-5); scene.add(fill);
const floorMat=new THREE.MeshStandardMaterial({color:'#e4c8ad',roughness:1});
const floor=new THREE.Mesh(new THREE.PlaneGeometry(200,200),floorMat); floor.rotation.x=-Math.PI/2; floor.position.y=-.09; floor.receiveShadow=true; scene.add(floor);
const grid=new THREE.GridHelper(40,40,0xffffff,0xffffff); grid.position.y=-.075; grid.material.transparent=true; grid.material.opacity=.2; scene.add(grid);
const worldGroup=new THREE.Group(); scene.add(worldGroup); const avatarRoot=new THREE.Group(); scene.add(avatarRoot); const modelGroup=new THREE.Group(); scene.add(modelGroup);
const mats={skin:new THREE.MeshStandardMaterial({color:'#e6b894',roughness:.8}),white:new THREE.MeshStandardMaterial({color:'#fbf5eb',roughness:.8}),dark:new THREE.MeshStandardMaterial({color:'#252535',roughness:.85}),shirt:new THREE.MeshStandardMaterial({color:'#a995ff',roughness:.8}),pants:new THREE.MeshStandardMaterial({color:'#33364e',roughness:.9}),hair:new THREE.MeshStandardMaterial({color:'#382a3d',roughness:.85}),shoe:new THREE.MeshStandardMaterial({color:'#f4f2ee',roughness:.8})};
const rig={}; const roundBox=(w,h,d,r,mat)=>{let mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat); mesh.castShadow=true;mesh.receiveShadow=true; return mesh};
function makeAvatar(){
 avatarRoot.clear();
 const body=new THREE.Group();avatarRoot.add(body);rig.body=body;
 const torso=roundBox(.93,1.05,.48,.12,mats.shirt);torso.position.y=1.52;body.add(torso);
 const neck=new THREE.Mesh(new THREE.CylinderGeometry(.16,.18,.22,12),mats.skin);neck.position.y=2.13;neck.castShadow=true;body.add(neck);
 const head=roundBox(.83,.82,.78,.14,mats.skin);head.position.set(0,2.67,0);body.add(head);rig.head=head;
 const faceCanvas=document.createElement('canvas');faceCanvas.width=256;faceCanvas.height=256;const ctx=faceCanvas.getContext('2d');
 const faceTex=new THREE.CanvasTexture(faceCanvas);faceTex.colorSpace=THREE.SRGBColorSpace; const faceMat=new THREE.MeshBasicMaterial({map:faceTex,transparent:true,side:THREE.DoubleSide});
 const face=new THREE.Mesh(new THREE.PlaneGeometry(.61,.55),faceMat);face.position.set(0,2.66,.397);body.add(face);rig.faceCtx=ctx;rig.faceTex=faceTex;
 const armL=new THREE.Group(),armR=new THREE.Group();armL.position.set(-.58,1.9,0);armR.position.set(.58,1.9,0);body.add(armL,armR);rig.armL=armL;rig.armR=armR;
 for(const a of [armL,armR]){let sleeve=roundBox(.33,.75,.35,.08,mats.shirt);sleeve.position.y=-.32;a.add(sleeve);let hand=new THREE.Mesh(new THREE.SphereGeometry(.19,16,12),mats.skin);hand.position.y=-.76;hand.castShadow=true;a.add(hand)}
 const legL=new THREE.Group(),legR=new THREE.Group();legL.position.set(-.25,1.04,0);legR.position.set(.25,1.04,0);body.add(legL,legR);rig.legL=legL;rig.legR=legR;
 for(const l of [legL,legR]){let pants=roundBox(.4,.83,.4,.06,mats.pants);pants.position.y=-.38;l.add(pants);let shoe=roundBox(.43,.2,.57,.07,mats.shoe);shoe.position.set(0,-.82,.06);l.add(shoe)}
 rig.hairGroup=new THREE.Group();body.add(rig.hairGroup); buildHair(0); drawFace();
}
function drawFace(){const c=rig.faceCtx;if(!c)return;c.clearRect(0,0,256,256);c.fillStyle='#302733';c.textAlign='center';c.textBaseline='middle';c.font='bold 59px Arial';c.fillText($('#eyes')?.value||'• •',128,105);c.font='bold 55px Arial';c.fillText($('#mouth')?.value||'ᴗ',128,178);rig.faceTex.needsUpdate=true;}
const hairStyles=[['Cloud curls','☁'],['Side sweep','〰'],['Spiky','✦'],['Beanie','▰'],['Bun','◉'],['Long waves','〽'],['Cap','⌂'],['Bald','○']];
function buildHair(index){if(!rig.hairGroup)return;rig.hairGroup.clear();const hairColors=['#382a3d','#df9557','#151820','#e4c35b','#8c4f73','#4a82a3'];mats.hair.color.set(hairColors[window.hairColor||0]);let g=new THREE.Group();rig.hairGroup.add(g);let style=index%hairStyles.length;
 if(style===7)return;
 if(style===0){let cap=new THREE.Mesh(new THREE.SphereGeometry(.46,20,14,0,Math.PI*2,0,Math.PI*.56),mats.hair);cap.position.y=3.0;g.add(cap);for(let i=0;i<7;i++){let p=new THREE.Mesh(new THREE.SphereGeometry(.19,12,10),mats.hair);p.position.set(Math.cos(i*.9)*.35,2.94+Math.sin(i*1.7)*.12,Math.sin(i*.9)*.32);g.add(p)}}
 else if(style===1||style===5){let cap=new THREE.Mesh(new THREE.SphereGeometry(.44,18,12,0,Math.PI*2,0,Math.PI*.53),mats.hair);cap.position.y=3.01;g.add(cap);for(let i=0;i<(style===5?5:2);i++){let w=new THREE.Mesh(new THREE.CapsuleGeometry(.09,.85,4,8),mats.hair);w.position.set(style===5?-.32+i*.16:.31,2.55,-.03);w.rotation.z=(style===5?.1:-.12);g.add(w)}}
 else if(style===2){for(let i=0;i<6;i++){let p=new THREE.Mesh(new THREE.ConeGeometry(.15,.43,5),mats.hair);p.position.set((i%3-.9)*.26,3.12,Math.floor(i/3)*.25-.12);p.rotation.z=(i%2?.18:-.18);g.add(p)}}
 else if(style===3||style===6){let b=new THREE.Mesh(new THREE.CylinderGeometry(.43,.45,.2,20),new THREE.MeshStandardMaterial({color:style===3?'#d85e75':'#4768ae',roughness:.8}));b.position.y=3.02;g.add(b);let top=new THREE.Mesh(new THREE.SphereGeometry(.42,20,10,0,Math.PI*2,0,Math.PI*.42),b.material);top.position.y=3.08;g.add(top);if(style===6){let brim=roundBox(.65,.07,.45,.04,b.material);brim.position.set(0,2.99,.26);g.add(brim)}}
 else {let cap=new THREE.Mesh(new THREE.SphereGeometry(.39,16,12),mats.hair);cap.position.set(0,3.07,-.04);g.add(cap)}
}
makeAvatar();
const mapThemes=[['Sunset Boardwalk','#f2a17e','#f9d79a','#74556d','🌅'],['Cloudtop City','#98c7e2','#def2ff','#7794b9','☁️'],['Moonlight Lagoon','#344b83','#7399ce','#273a6b','🌙'],['Candy Coast','#f69cbc','#ffe2d3','#a65e91','🍬'],['Mossy Meadow','#a6c984','#e1e9ae','#678d68','🌿'],['Neon Arcade','#5741a1','#d848d8','#252353','🎮'],['Cherry Blossom','#f5b8c2','#ffe1d0','#97608d','🌸'],['Frostpeak Lodge','#a8d7e8','#f1f8ff','#7188aa','❄️'],['Coral Carnival','#ef9f81','#f8db93','#805886','🎡'],['Crystal Cavern','#6b7ed1','#b5baff','#38417d','💎']];
const mapNames=[...mapThemes.map(x=>x[0]),'Aurora Falls','Pixel Plaza','Dino Island','Starlight Station','Wildflower Hill','Bubble Bay','Volcano Valley','Marshmallow Park','Jungle Ruins','Rainbow Ridge','Skatepark','Desert Dunes','Oceanarium','Rooftop Garden','Gumdrop Grove','Cloud Castle','Retro Mall','Sakura Street','Moonbase Zero','Lava Lagoon','Crystal Cove','Pinecone Village','Sunken Temple','Ice Cream Island','Meteor Shower','Mystic Forest','Coral Reef','Music Festival','Toybox Town','Butterfly Garden','Space Port','Pumpkin Patch','Waterfall Way','Peach Palace','Starfall Beach','Snowglobe City','Tropical Tides','Enchanted Library','Garden Party','Golden Gate','Windmill Fields','Mushroom Hollow','Soda Pop Springs','Robot Factory','Duskwood','Flower Market','Skyline Pier','Glacier Bay','Taffy Town','Firefly Forest','Koi Pond','Lunar Carnival','Honeycomb Hills','Sunbeam Station','Marble Maze','Palm Paradise','Cloud Nine','Raspberry Ridge','Glowworm Grotto','Seashell Shore','Puppet Theater','Bonsai Boulevard','Jellyfish Junction','Blueberry Bay','Paper Lantern Park','Copper Canyon','Dreamscape','Dandelion Downs','Cobalt Coast','Firework Festival','Lavender Lane','Starship Hangar','Cactus Canyon','Fairy Ring','Sundae Summit','Night Market','Wildwood Trail','Kite Day','Poppy Fields','Prism Peak','Velvet Valley','Lagoon Lookout','Comet Crossing','Sugarplum Square','Garden Galaxy','Sunset Speedway','Opal Orchard','Doodle District','Moonflower Meadow','Tinsel Town','Riverside Rink','Daydream Dock','Mango Marina','Stardust Summit','Clover Court','Rainbow Rail'];
const mapIndexByName={};mapNames.forEach((n,i)=>mapIndexByName[n]=i);
function themeFor(i){return mapThemes[i%mapThemes.length]}
function createMap(i){let [name,sky,ground,accent,emoji]=themeFor(i);scene.background.set(sky);scene.fog.color.set(sky);floorMat.color.set(ground); grid.material.color.set('#ffffff');$('#mapTitle').textContent=name;$('#mapIndex').textContent=String(i+1).padStart(2,'0');$('#mapBadgeEmoji')?.remove();worldGroup.clear();
 const platformMat=new THREE.MeshStandardMaterial({color:ground,roughness:.92});let island=new THREE.Mesh(new THREE.CylinderGeometry(5.5,5.9,.45,64),platformMat);island.position.y=-.36;island.receiveShadow=true;island.castShadow=true;worldGroup.add(island);
 const rim=new THREE.Mesh(new THREE.TorusGeometry(5.55,.08,8,64),new THREE.MeshStandardMaterial({color:accent,roughness:.65}));rim.rotation.x=Math.PI/2;rim.position.y=-.12;worldGroup.add(rim);
 // Cute layered scenery: trees, rocks, lamp posts and distant decorative forms.
 const colors=[accent,'#fff0c2','#9edfd0','#ed91a7','#7c8ce0'];
 for(let t=0;t<9;t++){let a=t/9*Math.PI*2+.2,r=4.05+(t%3)*.18,x=Math.cos(a)*r,z=Math.sin(a)*r;const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.12,.17,.8,8),new THREE.MeshStandardMaterial({color:'#765947'}));trunk.position.set(x,.26,z);trunk.castShadow=true;worldGroup.add(trunk);const top=new THREE.Mesh(new THREE.SphereGeometry(.48+(t%2)*.12,12,10),new THREE.MeshStandardMaterial({color:colors[t%colors.length],roughness:.8}));top.position.set(x,.91,z);top.castShadow=true;worldGroup.add(top)}
 for(let j=0;j<4;j++){let rock=new THREE.Mesh(new THREE.DodecahedronGeometry(.35+j%2*.13,0),new THREE.MeshStandardMaterial({color:colors[(j+2)%colors.length],roughness:.7}));rock.position.set(Math.cos(j*2.7)*3.2,.06,Math.sin(j*2.7)*3.2);rock.scale.y=.65;rock.castShadow=true;worldGroup.add(rock)}
 const platformTop=new THREE.Mesh(new THREE.CircleGeometry(5.48,64),new THREE.MeshStandardMaterial({color:ground,roughness:1}));platformTop.rotation.x=-Math.PI/2;platformTop.position.y=-.12;platformTop.receiveShadow=true;worldGroup.add(platformTop);
}
createMap(0);

