createMap(0);

const outfitData={
 tops:[['Lilac hoodie','💜','#a995ff'],['Sunset tee','🌇','#f28f72'],['Mint varsity','🍃','#69d6bd'],['Star jacket','⭐','#374378'],['Cherry knit','🍒','#d84e73'],['Cloud sweater','☁️','#ecedf5'],['Pixel shirt','🟦','#4778c8'],['Golden vest','✨','#efb84c']],
 bottoms:[['Night joggers','🩳','#36394e'],['Denim shorts','👖','#557ca5'],['Coral skirt','🩷','#ed8cad'],['Cargo pants','🥾','#778b61'],['Cloud trousers','🤍','#eceaf1'],['Star leggings','🌟','#5245a1']],
 hair:hairStyles.map((x,i)=>[x[0],x[1],['#382a3d','#df9557','#151820','#e4c35b','#8c4f73','#4a82a3','#4768ae','#aaa'][i]])
};
let selectedWardrobe='tops', selectedMotion='idle', selectedMap=0, selectedTop=0, selectedBottom=0, selectedHair=0, modelCount=0, isPlaying=true, recorded=false;
const colorFromHex=c=>new THREE.Color(c);
function renderOutfit(){const wrap=$('#itemList');wrap.innerHTML='';outfitData[selectedWardrobe].forEach((item,i)=>{const b=document.createElement('button');b.className='item-card'+((selectedWardrobe==='tops'?i===selectedTop:selectedWardrobe==='bottoms'?i===selectedBottom:i===selectedHair)?' active':'');b.innerHTML=`<div class="item-icon">${item[1]}</div>${item[0]}`;b.onclick=()=>{if(selectedWardrobe==='tops'){selectedTop=i;mats.shirt.color.set(item[2])}else if(selectedWardrobe==='bottoms'){selectedBottom=i;mats.pants.color.set(item[2])}else{selectedHair=i;buildHair(i)}renderOutfit();toast(`${item[0]} equipped`) };wrap.appendChild(b)})}
function renderMaps(filter=''){const grid=$('#mapGrid');grid.innerHTML='';mapNames.forEach((name,i)=>{if(filter&&!name.toLowerCase().includes(filter.toLowerCase()))return;const th=themeFor(i),b=document.createElement('button');b.className='map-card'+(i===selectedMap?' active':'');b.innerHTML=`<span class="map-art" style="background:linear-gradient(145deg,${th[1]},${th[2]} 60%,${th[3]})"></span><span class="map-number">${String(i+1).padStart(2,'0')}</span><span class="map-caption">${name}</span>`;b.onclick=()=>selectMap(i);grid.appendChild(b)});}
function selectMap(i){selectedMap=i;createMap(i);renderMaps($('#mapSearch').value);toast(`Welcome to ${mapNames[i]}`)}
const skinPresets=['#f8d7bd','#e6b894','#c68663','#995f49','#69473d','#f2cfa0'];const swatchBox=$('#swatches');skinPresets.forEach((c,i)=>{const b=document.createElement('button');b.className='swatch'+(i===1?' selected':'');b.style.background=c;b.title=c;b.onclick=()=>setSkin(c);swatchBox.appendChild(b)});
function setSkin(c){mats.skin.color.set(c);$('#skinPicker').value=c;$('#skinHex').textContent=c.toUpperCase();$$('.swatch').forEach(x=>x.classList.toggle('selected',x.title.toLowerCase()===c.toLowerCase()));}
$('#skinPicker').addEventListener('input',e=>setSkin(e.target.value));$('#eyes').onchange=drawFace;$('#mouth').onchange=drawFace;
$$('#wardrobeTabs .tab').forEach(b=>b.onclick=()=>{$$('#wardrobeTabs .tab').forEach(x=>x.classList.toggle('active',x===b));selectedWardrobe=b.dataset.type;renderOutfit()});renderOutfit();renderMaps();
const motionButtons=$$('#motionButtons .feature');motionButtons.forEach(b=>b.onclick=()=>{motionButtons.forEach(x=>x.classList.toggle('active',x===b));selectedMotion=b.dataset.motion;if(['dance','walk','wave','jump','run'].includes(selectedMotion))isPlaying=true;toast(`${b.textContent.trim()} animation`) });
$('#heightRange').oninput=e=>{$('#heightValue').value=e.target.value+'%';avatarRoot.scale.set(1,e.target.value/100,1)};
$('#mapSearch').oninput=e=>renderMaps(e.target.value);$('#randomMap').onclick=()=>selectMap(Math.floor(Math.random()*100));
const primitiveItems=[['Cube','▧','box'],['Sphere','●','sphere'],['Tree','🌳','tree'],['Lamp','💡','lamp'],['Cloud','☁️','cloud'],['Star','⭐','star'],['Stage','▰','stage'],['Crystal','💎','crystal']];
$('#primitiveGrid').innerHTML=primitiveItems.map(x=>`<button class="primitive" data-kind="${x[2]}"><span>${x[1]}</span>${x[0]}</button>`).join('');
function addModel(kind){const g=new THREE.Group(),mat=new THREE.MeshStandardMaterial({color:['#a995ff','#6be1d2','#ffad7d','#f5d276'][modelCount%4],roughness:.65});let mesh;
 if(kind==='sphere')mesh=new THREE.Mesh(new THREE.IcosahedronGeometry(.55,1),mat);
 else if(kind==='tree'){let trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13,.18,.7,8),new THREE.MeshStandardMaterial({color:'#805638'}));trunk.position.y=.35;g.add(trunk);mesh=new THREE.Mesh(new THREE.SphereGeometry(.55,12,10),mat);mesh.position.y=.95}
 else if(kind==='lamp'){let pole=new THREE.Mesh(new THREE.CylinderGeometry(.055,.08,1.3,8),new THREE.MeshStandardMaterial({color:'#40465a',metalness:.5}));pole.position.y=.65;g.add(pole);mesh=new THREE.Mesh(new THREE.SphereGeometry(.24,16,12),new THREE.MeshStandardMaterial({color:'#ffe79a',emissive:'#ffbd51',emissiveIntensity:1.6}));mesh.position.y=1.38}
 else if(kind==='cloud'){mesh=new THREE.Group();for(let i=0;i<5;i++){let p=new THREE.Mesh(new THREE.SphereGeometry(.35+(i%2)*.08,12,10),new THREE.MeshStandardMaterial({color:'#f4f4f8',roughness:1}));p.position.set((i-2)*.25,.25+Math.sin(i)*.08,0);mesh.add(p)}mesh.position.y=1.3}
 else if(kind==='star'){mesh=new THREE.Mesh(new THREE.OctahedronGeometry(.6,0),mat);mesh.scale.y=1.4}
 else if(kind==='stage'){mesh=new THREE.Mesh(new THREE.CylinderGeometry(.75,.85,.18,32),mat);mesh.position.y=.08}
 else if(kind==='crystal'){mesh=new THREE.Mesh(new THREE.OctahedronGeometry(.6,0),new THREE.MeshStandardMaterial({color:'#81eff0',metalness:.45,roughness:.2,transparent:true,opacity:.88}));mesh.position.y=.55;mesh.scale.y=1.6}
 else mesh=new THREE.Mesh(new THREE.BoxGeometry(.8,.8,.8),mat);
 if(mesh){mesh.castShadow=true;mesh.receiveShadow=true;g.add(mesh)}g.position.set((Math.random()-.5)*3,.12,(Math.random()-.5)*2-1);g.userData={kind,id:++modelCount};modelGroup.add(g);addModelRow(kind,g.userData.id);$('#modelModal').classList.remove('open');toast(`${kind[0].toUpperCase()+kind.slice(1)} added to scene`);}
function addModelRow(kind,id){const list=$('#modelList');if(!list)return;let row=document.createElement('div');row.className='model-row';row.dataset.id=id;row.innerHTML=`<span class="emoji">${(primitiveItems.find(x=>x[2]===kind)||[])[1]||'▧'}</span><span>${kind[0].toUpperCase()+kind.slice(1)} ${id}</span><button aria-label="Delete model">×</button>`;row.querySelector('button').onclick=()=>{const obj=modelGroup.children.find(x=>x.userData.id===id);if(obj)modelGroup.remove(obj);row.remove();toast('Model removed')};list.appendChild(row)}
$$('.primitive').forEach(b=>b.onclick=()=>addModel(b.dataset.kind));

